{
  "name": "SubCalculator Pro",
  "description": "A decision-grade In-App Subscription Business Model Calculator. Model cohorts, LTV, CAC, payback periods, and profitability scenarios with precision."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type PlanType = 'weekly' | 'monthly' | 'annual' | 'lifetime';

export interface MarketingInput {
  adSpend: number; // Monthly recurring or array
  cpi: number;
  organicMultiplier: number; // e.g. 0.5 means 50% boost
}

export interface FunnelInput {
  usingTrial: boolean;
  installToTrialRate: number; // 0-1
  trialToPaidRate: number; // 0-1
  installToPaidRate: number; // 0-1 (if no trial)
  refundRate: number; // 0-1
  planMix: {
    weekly: number;
    monthly: number;
    annual: number;
    lifetime: number;
  };
}

export interface PlanConfig {
  price: number;
  storeCommissionYear1: number;
  storeCommissionYear2Plus: number;
  // For simplicity in this monthly model, we assume specific behaviors per plan type
}

export interface RetentionInput {
  // Mode: 'simple' (churn parameters) or 'advanced' (month-by-month table)
  mode: 'simple' | 'advanced';

  // Simple Mode Params
  monthly: {
    month1Churn: number;
    steadyStateChurn: number;
    decayFactor: number; // 0-1, how fast it drops to steady state
  };
  annual: {
    year1Churn: number;
    steadyStateChurn: number;
  };
  weekly: {
    week1Churn: number;
    steadyStateChurn: number;
  };

  // Advanced Mode (simplified to just arrays of survival rates for this demo, usually would be explicit renewal rates)
  // We'll stick to computing survival curves from the params for the MVP to reduce UI complexity
}

export interface CostsInput {
  fixedOpexMonthly: number;
  variableCostPerActiveSub: number;
  variableCostPerInstall: number;
  supportCostPerTicket: number;
  ticketsPer1000Subs: number;
}

export interface ScenarioInput {
  id: string;
  name: string;
  horizonMonths: number;
  marketing: MarketingInput;
  funnel: FunnelInput;
  plans: Record<PlanType, PlanConfig>;
  retention: RetentionInput;
  costs: CostsInput;
}

export interface MonthlyMetric {
  monthIndex: number; // 1-based
  adSpend: number;
  cpi: number;
  paidInstalls: number;
  organicInstalls: number;
  totalInstalls: number;

  trials: number;
  newPayers: number;
  newPayersByPlan: Record<PlanType, number>;

  activeSubsTotal: number;
  activeSubsByPlan: Record<PlanType, number>;

  grossRevenue: number;
  netRevenue: number;

  variableCosts: number;
  fixedOpex: number;
  totalExpenses: number;

  contributionMargin: number;
  profit: number;
  cumulativeProfit: number;

  mrr: number;
}

export interface ModelOutput {
  monthlyData: MonthlyMetric[];
  summary: {
    ltvPerPayer: number;
    cacPerPayer: number;
    ltvCacRatio: number;
    paybackPeriodMonths: number | null; // null if never
    breakEvenMonth: number | null;
    totalProfit: number;
    maxNegativeCashflow: number;
  };
  // Cohort analysis for a single theoretical cohort to determine LTV/Payback curves
  theoreticalCohort: {
    month: number;
    netRevenueCum: number;
    contributionCum: number;
    cac: number;
  }[];
}

import { ScenarioInput } from './types';

export const DEFAULT_SCENARIO: ScenarioInput = {
  id: 'default',
  name: 'Base Case',
  horizonMonths: 24,
  marketing: {
    adSpend: 10000,
    cpi: 2.50,
    organicMultiplier: 0.2, // 20% organic uplift
  },
  funnel: {
    usingTrial: true,
    installToTrialRate: 0.15,
    trialToPaidRate: 0.60,
    installToPaidRate: 0.05, // ignored if usingTrial
    refundRate: 0.05,
    planMix: {
      weekly: 0.0,
      monthly: 0.6,
      annual: 0.4,
      lifetime: 0.0,
    },
  },
  plans: {
    weekly: {
      price: 4.99,
      storeCommissionYear1: 0.30,
      storeCommissionYear2Plus: 0.15,
    },
    monthly: {
      price: 9.99,
      storeCommissionYear1: 0.30,
      storeCommissionYear2Plus: 0.15,
    },
    annual: {
      price: 59.99,
      storeCommissionYear1: 0.30,
      storeCommissionYear2Plus: 0.15,
    },
    lifetime: {
      price: 199.99,
      storeCommissionYear1: 0.30,
      storeCommissionYear2Plus: 0.15,
    },
  },
  retention: {
    mode: 'simple',
    weekly: {
      week1Churn: 0.20,
      steadyStateChurn: 0.10,
    },
    monthly: {
      month1Churn: 0.15,
      steadyStateChurn: 0.05,
      decayFactor: 0.5,
    },
    annual: {
      year1Churn: 0.40,
      steadyStateChurn: 0.20,
    },
  },
  costs: {
    fixedOpexMonthly: 5000,
    variableCostPerActiveSub: 0.10, // Server costs etc
    variableCostPerInstall: 0.00,
    supportCostPerTicket: 5.00,
    ticketsPer1000Subs: 10,
  },
};

import { ScenarioInput, ModelOutput, MonthlyMetric, PlanType } from '../types';

// Helper to generate a decay curve
function generateSurvivalCurve(
  initialChurn: number,
  steadyStateChurn: number,
  decayFactor: number,
  periods: number
): number[] {
  const survivalRates: number[] = [1.0]; // Period 0 is 100%
  let currentChurn = initialChurn;

  for (let i = 1; i < periods; i++) {
    const prevSurvival = survivalRates[i - 1];
    const survived = prevSurvival * (1 - currentChurn);
    survivalRates.push(survived);

    // Decay churn towards steady state
    currentChurn = currentChurn - (currentChurn - steadyStateChurn) * decayFactor;
    // Safety clamp
    if (currentChurn < steadyStateChurn) currentChurn = steadyStateChurn;
  }
  return survivalRates;
}

export function calculateModel(input: ScenarioInput): ModelOutput {
  const { horizonMonths, marketing, funnel, plans, retention, costs } = input;

  // 1. Pre-calculate Retention Curves (Survival Probability per month since purchase)
  // We project out to horizon + 12 to handle edge effects
  const projectionLength = horizonMonths + 24; 

  const survivalCurves: Record<PlanType, number[]> = {
    weekly: [],
    monthly: [],
    annual: [],
    lifetime: []
  };

  // Monthly Curve
  survivalCurves.monthly = generateSurvivalCurve(
    retention.monthly.month1Churn,
    retention.monthly.steadyStateChurn,
    retention.monthly.decayFactor,
    projectionLength
  );

  // Annual Curve
  // Annual is tricky in a monthly model. We treat them as "active" for 12 months.
  // Then at month 12, they drop off based on Year 1 Churn.
  const annualSurvival: number[] = [];
  for(let m=0; m < projectionLength; m++) {
    const yearIndex = Math.floor(m / 12);
    // Simple Step Function for Annual:
    // Year 0 (Months 0-11): 100% (of the cohort)
    // Year 1 (Months 12-23): (1 - year1Churn)
    // Year 2 (Months 24-35): (1 - year1Churn) * (1 - steadyStateChurn)

    let rate = 1.0;
    if (yearIndex >= 1) rate *= (1 - retention.annual.year1Churn);
    for(let y=2; y <= yearIndex; y++) {
      rate *= (1 - retention.annual.steadyStateChurn);
    }
    annualSurvival.push(rate);
  }
  survivalCurves.annual = annualSurvival;

  // Weekly Curve (Approximation for Monthly Model)
  // We model effective monthly survival.
  // Effective Monthly Churn ~= 1 - (1 - weeklyChurn)^4.33
  const avgWeeksPerMonth = 52 / 12; // 4.33
  const effectiveMonthlyChurnInitial = 1 - Math.pow(1 - retention.weekly.week1Churn, avgWeeksPerMonth);
  const effectiveMonthlyChurnSteady = 1 - Math.pow(1 - retention.weekly.steadyStateChurn, avgWeeksPerMonth);

  survivalCurves.weekly = generateSurvivalCurve(
    effectiveMonthlyChurnInitial,
    effectiveMonthlyChurnSteady,
    0.5, // fast decay
    projectionLength
  );

  // Lifetime Curve (Always 1.0 unless we model death, let's assume 1.0)
  survivalCurves.lifetime = new Array(projectionLength).fill(1.0);


  // 2. Initialize Monthly Data Array
  const monthlyData: MonthlyMetric[] = [];
  let cumulativeProfit = 0;

  // Track active cohorts to sum up metrics
  // cohorts[plan][cohortStartMonth] = numberOfPayers
  const cohorts: Record<PlanType, number[]> = {
    weekly: new Array(horizonMonths + 1).fill(0),
    monthly: new Array(horizonMonths + 1).fill(0),
    annual: new Array(horizonMonths + 1).fill(0),
    lifetime: new Array(horizonMonths + 1).fill(0),
  };

  for (let m = 1; m <= horizonMonths; m++) {
    // A. Acquisition
    const paidInstalls = marketing.adSpend / (marketing.cpi || 999999);
    const organicInstalls = paidInstalls * marketing.organicMultiplier;
    const totalInstalls = paidInstalls + organicInstalls;

    // B. Funnel
    let newPayers = 0;
    let trials = 0;

    if (funnel.usingTrial) {
      trials = totalInstalls * funnel.installToTrialRate;
      newPayers = trials * funnel.trialToPaidRate;
    } else {
      newPayers = totalInstalls * funnel.installToPaidRate;
    }

    const newPayersByPlan = {
      weekly: newPayers * funnel.planMix.weekly,
      monthly: newPayers * funnel.planMix.monthly,
      annual: newPayers * funnel.planMix.annual,
      lifetime: newPayers * funnel.planMix.lifetime,
    };

    // Record cohort size
    cohorts.weekly[m] = newPayersByPlan.weekly;
    cohorts.monthly[m] = newPayersByPlan.monthly;
    cohorts.annual[m] = newPayersByPlan.annual;
    cohorts.lifetime[m] = newPayersByPlan.lifetime;

    // C. Revenue & Active Subs Calculation (Summing all historical cohorts)
    let activeSubsTotal = 0;
    const activeSubsByPlan = { weekly: 0, monthly: 0, annual: 0, lifetime: 0 };
    let grossRevenue = 0;
    let netRevenue = 0;
    let mrr = 0;

    // Iterate all plans
    (Object.keys(plans) as PlanType[]).forEach(plan => {
      let planActive = 0;
      let planGross = 0;
      let planNet = 0;

      const price = plans[plan].price;
      const commY1 = plans[plan].storeCommissionYear1;
      const commY2 = plans[plan].storeCommissionYear2Plus;

      // Iterate past cohorts (c = cohort start month)
      for (let c = 1; c <= m; c++) {
        const cohortSize = cohorts[plan][c];
        if (cohortSize <= 0.001) continue;

        const ageMonths = m - c; // 0 for first month
        const survivalRate = survivalCurves[plan][ageMonths] || 0;
        const activeCount = cohortSize * survivalRate;

        // Add to active count
        planActive += activeCount;

        // Calculate Revenue
        // Is this a billing month?
        let isBilling = false;
        let billingMultiplier = 1;

        if (plan === 'monthly') {
          isBilling = true; 
        } else if (plan === 'weekly') {
          isBilling = true;
          billingMultiplier = 52/12; // Approx 4.33 payments per month
        } else if (plan === 'annual') {
          isBilling = (ageMonths % 12 === 0);
        } else if (plan === 'lifetime') {
          isBilling = (ageMonths === 0);
        }

        if (isBilling) {
          const revenueEvent = activeCount * price * billingMultiplier;
          planGross += revenueEvent;

          // Commission
          const isYear1 = ageMonths < 12;
          const commissionRate = isYear1 ? commY1 : commY2;
          const afterComm = revenueEvent * (1 - commissionRate);

          // Refunds
          const afterRefund = afterComm * (1 - funnel.refundRate);
          planNet += afterRefund;
        }

        // MRR Contribution
        if (plan === 'monthly') mrr += activeCount * price;
        if (plan === 'weekly') mrr += activeCount * price * (52/12);
        if (plan === 'annual') mrr += activeCount * (price / 12);
        // Lifetime usually doesn't count towards MRR, or is smoothed. We'll exclude lifetime from MRR.
      }

      activeSubsByPlan[plan] = planActive;
      activeSubsTotal += planActive;
      grossRevenue += planGross;
      netRevenue += planNet;
    });

    // D. Costs
    const supportCosts = (costs.supportCostPerTicket * costs.ticketsPer1000Subs * (activeSubsTotal / 1000));
    const varCostSubs = activeSubsTotal * costs.variableCostPerActiveSub;
    const varCostInstalls = totalInstalls * costs.variableCostPerInstall;
    const variableCosts = supportCosts + varCostSubs + varCostInstalls;

    const fixedOpex = costs.fixedOpexMonthly;
    const totalExpenses = marketing.adSpend + variableCosts + fixedOpex;

    const contributionMargin = netRevenue - variableCosts - marketing.adSpend; // Wait, adSpend usually separate in contrib defs?
    // Definition from prompt: Contribution[t] = NetRevenue[t] - VariableCosts[t]
    // Prompt says: Payback = cumulative contribution >= CAC.
    // So Contribution here usually excludes Fixed Opex but INCLUDES Ad Spend for "Business" contribution?
    // Let's stick to prompt definition: Contribution[t] = NetRevenue[t] - VariableCosts[t].
    // Note: Ad Spend is technically a discretionary investment (CAC).
    // The Profit equation: Profit[t] = Contribution[t] - FixedOpex[t] - AdSpend (wait, prompt definition for Profit?)
    // Prompt: Profit[t] = Contribution[t] - FixedOpex[t].
    // Wait, VariableCosts definition in prompt: "variableCostPerActiveSubscriber... + infra". It does NOT list adSpend.
    // So Profit[t] needs to subtract AdSpend somewhere?
    // Usually Profit = NetRevenue - COGS - Opex - Marketing.
    // Let's assume Profit[t] = NetRevenue[t] - VariableCosts[t] - FixedOpex[t] - AdSpend[t].

    const trueContribution = netRevenue - variableCosts;
    const profit = trueContribution - fixedOpex - marketing.adSpend;

    cumulativeProfit += profit;

    monthlyData.push({
      monthIndex: m,
      adSpend: marketing.adSpend,
      cpi: marketing.cpi,
      paidInstalls,
      organicInstalls,
      totalInstalls,
      trials,
      newPayers,
      newPayersByPlan,
      activeSubsTotal,
      activeSubsByPlan,
      grossRevenue,
      netRevenue,
      variableCosts,
      fixedOpex,
      totalExpenses,
      contributionMargin: trueContribution,
      profit,
      cumulativeProfit,
      mrr
    });
  }

  // 3. Summary & Theoretical Cohort for LTV/CAC
  // We simulate ONE single user per plan mix through their lifetime (60 months)
  const theoreticalHorizon = 60;
  let ltvGross = 0;
  let ltvNet = 0;
  let theoreticalCac = marketing.cpi / (funnel.usingTrial ? (funnel.installToTrialRate * funnel.trialToPaidRate) : funnel.installToPaidRate);
  // Adjust CAC for organic multiplier.
  // Effective CAC = AdSpend / TotalNewPayers
  // TotalNewPayers = (AdSpend/CPI * (1+OrganicMult)) * Conversion
  // So EffCAC = AdSpend / (AdSpend/CPI * (1+Org) * Conv) = CPI / ((1+Org)*Conv)
  const conversionRate = funnel.usingTrial ? (funnel.installToTrialRate * funnel.trialToPaidRate) : funnel.installToPaidRate;
  const effectiveCac = marketing.cpi / ((1 + marketing.organicMultiplier) * conversionRate);

  const theoreticalCohort: { month: number, netRevenueCum: number, contributionCum: number, cac: number }[] = [];
  let cumNetRev = 0;

  // Mix-weighted Average Revenue Per Month Per Initial Payer
  for (let t = 0; t < theoreticalHorizon; t++) {
    let monthlyNetRevPerPayer = 0;

    // Iterate plans
    (Object.keys(plans) as PlanType[]).forEach(plan => {
        const share = funnel.planMix[plan];
        if (share === 0) return;

        const survival = survivalCurves[plan][t] || 0;
        const price = plans[plan].price;
        const commY1 = plans[plan].storeCommissionYear1;
        const commY2 = plans[plan].storeCommissionYear2Plus;

        let revenue = 0;
        let isBilling = false;
        let mult = 1;

        if (plan === 'monthly') isBilling = true;
        if (plan === 'weekly') { isBilling = true; mult = 52/12; }
        if (plan === 'annual') isBilling = (t % 12 === 0);
        if (plan === 'lifetime') isBilling = (t === 0);

        if (isBilling) {
            const rawRev = price * mult;
            const comm = t < 12 ? commY1 : commY2;
            const net = rawRev * (1 - comm) * (1 - funnel.refundRate);
            revenue = net;
        }

        // Variable cost per active sub
        // We deduct this from LTV to get "Net LTV" (Contribution LTV)
        // Note: Variable costs apply every month user is active
        const cost = (survival > 0) ? (costs.variableCostPerActiveSub + (costs.supportCostPerTicket * costs.ticketsPer1000Subs/1000)) : 0;

        monthlyNetRevPerPayer += share * survival * (revenue - cost);
    });

    cumNetRev += monthlyNetRevPerPayer;
    theoreticalCohort.push({
        month: t + 1,
        netRevenueCum: cumNetRev,
        contributionCum: cumNetRev, // Variable costs already deducted above
        cac: effectiveCac
    });
  }

  ltvNet = cumNetRev;

  // Payback Month
  const paybackMonth = theoreticalCohort.find(p => p.contributionCum >= effectiveCac)?.month || null;
  const breakEvenMonthData = monthlyData.find(m => m.cumulativeProfit >= 0);

  // Summaries
  const totalProfit = cumulativeProfit;
  const minCash = Math.min(...monthlyData.map(m => m.cumulativeProfit));

  return {
    monthlyData,
    summary: {
      ltvPerPayer: ltvNet,
      cacPerPayer: effectiveCac,
      ltvCacRatio: effectiveCac > 0 ? ltvNet / effectiveCac : 0,
      paybackPeriodMonths: paybackMonth,
      breakEvenMonth: breakEvenMonthData ? breakEvenMonthData.monthIndex : null,
      totalProfit,
      maxNegativeCashflow: minCash
    },
    theoreticalCohort
  };
}

import { create } from 'zustand';
import { DEFAULT_SCENARIO } from './constants';
import { ScenarioInput, ModelOutput } from './types';
import { calculateModel } from './utils/calculations';

interface AppState {
  activeScenario: ScenarioInput;
  results: ModelOutput;

  // Actions
  updateScenario: (partial: Partial<ScenarioInput>) => void;
  updateNestedScenario: <K extends keyof ScenarioInput>(
    section: K, 
    data: Partial<ScenarioInput[K]>
  ) => void;
  resetScenario: () => void;
}

export const useStore = create<AppState>((set, get) => {
  // Initial calculation
  const initialResults = calculateModel(DEFAULT_SCENARIO);

  return {
    activeScenario: DEFAULT_SCENARIO,
    results: initialResults,

    updateScenario: (partial) => {
      set((state) => {
        const newScenario = { ...state.activeScenario, ...partial };
        return {
          activeScenario: newScenario,
          results: calculateModel(newScenario)
        };
      });
    },

    updateNestedScenario: (section, data) => {
      set((state) => {
        const newScenario = {
          ...state.activeScenario,
          [section]: {
            ...state.activeScenario[section],
            ...data
          }
        };
        return {
          activeScenario: newScenario,
          results: calculateModel(newScenario)
        };
      });
    },

    resetScenario: () => {
      set({
        activeScenario: DEFAULT_SCENARIO,
        results: calculateModel(DEFAULT_SCENARIO)
      });
    }
  };
});

import React from 'react';

interface NumberInputProps {
  label: string;
  value: number;
  onChange: (val: number) => void;
  step?: number;
  min?: number;
  max?: number;
  suffix?: string;
  tooltip?: string;
  isPercent?: boolean;
}

export const NumberInput: React.FC<NumberInputProps> = ({ 
  label, value, onChange, step = 1, min = 0, max, suffix, tooltip, isPercent 
}) => {
  const displayValue = isPercent ? Math.round(value * 100) : value;

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let val = parseFloat(e.target.value);
    if (isNaN(val)) val = 0;
    if (isPercent) val = val / 100;
    onChange(val);
  };

  return (
    <div className="mb-3">
      <div className="flex justify-between items-baseline mb-1">
        <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider flex items-center gap-1">
          {label}
          {tooltip && (
            <span className="text-slate-300 cursor-help" title={tooltip}>ⓘ</span>
          )}
        </label>
        {isPercent && <span className="text-xs text-slate-400">{(value * 100).toFixed(1)}%</span>}
      </div>
      <div className="relative">
        <input
          type="number"
          className="w-full bg-white border border-slate-200 rounded px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all"
          value={displayValue}
          onChange={handleChange}
          step={step}
          min={min}
          max={max}
        />
        {suffix && (
          <span className="absolute right-3 top-2 text-sm text-slate-400 pointer-events-none">
            {suffix}
          </span>
        )}
      </div>
    </div>
  );
};

export const SectionHeader: React.FC<{ title: string; isOpen: boolean; toggle: () => void }> = ({ title, isOpen, toggle }) => (
  <button 
    onClick={toggle}
    className="w-full flex items-center justify-between p-4 bg-slate-50 hover:bg-slate-100 border-b border-slate-200 transition-colors text-left"
  >
    <span className="font-bold text-slate-700">{title}</span>
    <span className={`transform transition-transform ${isOpen ? 'rotate-180' : ''}`}>▼</span>
  </button>
);

import React, { useState } from 'react';
import { useStore } from '../store';
import { NumberInput, SectionHeader } from './InputSection';
import { PlanType } from '../types';

export const Sidebar: React.FC = () => {
  const { activeScenario, updateScenario, updateNestedScenario } = useStore();

  // Collapsible state
  const [sections, setSections] = useState({
    marketing: true,
    funnel: true,
    plans: false,
    retention: false,
    costs: false
  });

  const toggle = (key: keyof typeof sections) => 
    setSections(prev => ({ ...prev, [key]: !prev[key] }));

  return (
    <div className="w-full lg:w-80 flex-shrink-0 bg-white border-r border-slate-200 h-screen overflow-y-auto custom-scrollbar">
      <div className="p-4 border-b border-slate-200 sticky top-0 bg-white z-10">
        <h1 className="text-xl font-black text-slate-800 tracking-tight">SubCalculator<span className="text-blue-600">Pro</span></h1>
        <p className="text-xs text-slate-400 mt-1">Growth Modeling Engine</p>
      </div>

      {/* Global Config */}
      <div className="p-4 border-b border-slate-200 bg-slate-50/50">
        <NumberInput 
          label="Forecast Horizon" 
          value={activeScenario.horizonMonths} 
          onChange={(v) => updateScenario({ horizonMonths: v })} 
          suffix="months"
          min={6} max={60}
        />
      </div>

      {/* 1. Marketing */}
      <SectionHeader title="1. Marketing & Acquisition" isOpen={sections.marketing} toggle={() => toggle('marketing')} />
      {sections.marketing && (
        <div className="p-4 space-y-2 animate-fadeIn">
          <NumberInput 
            label="Monthly Ad Spend" 
            value={activeScenario.marketing.adSpend} 
            onChange={(v) => updateNestedScenario('marketing', { adSpend: v })} 
            suffix="$" step={100}
          />
          <NumberInput 
            label="CPI (Cost Per Install)" 
            value={activeScenario.marketing.cpi} 
            onChange={(v) => updateNestedScenario('marketing', { cpi: v })} 
            suffix="$" step={0.1}
          />
          <NumberInput 
            label="Organic Uplift Multiplier" 
            value={activeScenario.marketing.organicMultiplier} 
            onChange={(v) => updateNestedScenario('marketing', { organicMultiplier: v })} 
            step={0.1} isPercent
            tooltip="0.5 means 50% additional organic installs"
          />
        </div>
      )}

      {/* 2. Funnel */}
      <SectionHeader title="2. Funnel Conversion" isOpen={sections.funnel} toggle={() => toggle('funnel')} />
      {sections.funnel && (
        <div className="p-4 space-y-2 animate-fadeIn">
           <div className="flex items-center gap-2 mb-4">
            <input 
              type="checkbox" 
              checked={activeScenario.funnel.usingTrial}
              onChange={(e) => updateNestedScenario('funnel', { usingTrial: e.target.checked })}
              className="rounded border-slate-300 text-blue-600 focus:ring-blue-500"
            />
            <label className="text-sm text-slate-700 font-medium">Use Free Trial Model</label>
           </div>

           {activeScenario.funnel.usingTrial ? (
             <>
                <NumberInput 
                  label="Install → Trial Rate" 
                  value={activeScenario.funnel.installToTrialRate} 
                  onChange={(v) => updateNestedScenario('funnel', { installToTrialRate: v })} 
                  step={1} isPercent
                />
                <NumberInput 
                  label="Trial → Paid Rate" 
                  value={activeScenario.funnel.trialToPaidRate} 
                  onChange={(v) => updateNestedScenario('funnel', { trialToPaidRate: v })} 
                  step={1} isPercent
                />
             </>
           ) : (
              <NumberInput 
                label="Install → Paid Rate" 
                value={activeScenario.funnel.installToPaidRate} 
                onChange={(v) => updateNestedScenario('funnel', { installToPaidRate: v })} 
                step={0.1} isPercent
              />
           )}

           <NumberInput 
              label="Refund Rate" 
              value={activeScenario.funnel.refundRate} 
              onChange={(v) => updateNestedScenario('funnel', { refundRate: v })} 
              step={0.5} isPercent
           />

           <div className="mt-4 pt-4 border-t border-slate-100">
             <h4 className="text-xs font-bold text-slate-800 uppercase mb-3">Plan Mix (Must sum to 100%)</h4>
             {(['weekly', 'monthly', 'annual', 'lifetime'] as const).map(p => (
                <NumberInput 
                  key={p}
                  label={`${p} Mix`} 
                  value={activeScenario.funnel.planMix[p]} 
                  onChange={(v) => {
                    const newMix = { ...activeScenario.funnel.planMix, [p]: v };
                    updateNestedScenario('funnel', { planMix: newMix });
                  }} 
                  step={1} isPercent
                />
             ))}
           </div>
        </div>
      )}

      {/* 3. Plans */}
      <SectionHeader title="3. Plans & Pricing" isOpen={sections.plans} toggle={() => toggle('plans')} />
      {sections.plans && (
        <div className="p-4 space-y-4 animate-fadeIn">
          {(['weekly', 'monthly', 'annual'] as PlanType[]).map(p => {
             if (activeScenario.funnel.planMix[p] === 0) return null;
             return (
              <div key={p} className="p-3 bg-slate-50 rounded border border-slate-100">
                 <h4 className="text-sm font-bold capitalize mb-2">{p} Plan</h4>
                 <NumberInput 
                    label="Price" 
                    value={activeScenario.plans[p].price} 
                    onChange={(v) => {
                      const newPlans = { ...activeScenario.plans };
                      newPlans[p] = { ...newPlans[p], price: v };
                      updateScenario({ plans: newPlans });
                    }} 
                    suffix="$"
                  />
              </div>
             );
          })}
        </div>
      )}

      {/* 4. Retention */}
      <SectionHeader title="4. Retention & Churn" isOpen={sections.retention} toggle={() => toggle('retention')} />
      {sections.retention && (
        <div className="p-4 space-y-4 animate-fadeIn">
          {activeScenario.funnel.planMix.weekly > 0 && (
            <div className="p-3 bg-slate-50 rounded border border-slate-100">
              <h4 className="text-sm font-bold capitalize mb-2">Weekly Retention</h4>
              <NumberInput 
                label="Week 1 Churn" 
                value={activeScenario.retention.weekly.week1Churn} 
                onChange={(v) => updateNestedScenario('retention', { weekly: { ...activeScenario.retention.weekly, week1Churn: v }})} 
                step={1} isPercent
              />
              <NumberInput 
                label="Steady State Churn" 
                value={activeScenario.retention.weekly.steadyStateChurn} 
                onChange={(v) => updateNestedScenario('retention', { weekly: { ...activeScenario.retention.weekly, steadyStateChurn: v }})} 
                step={1} isPercent
              />
            </div>
          )}
          {activeScenario.funnel.planMix.monthly > 0 && (
            <div className="p-3 bg-slate-50 rounded border border-slate-100">
              <h4 className="text-sm font-bold capitalize mb-2">Monthly Retention</h4>
              <NumberInput 
                label="Month 1 Churn" 
                value={activeScenario.retention.monthly.month1Churn} 
                onChange={(v) => updateNestedScenario('retention', { monthly: { ...activeScenario.retention.monthly, month1Churn: v }})} 
                step={1} isPercent
              />
              <NumberInput 
                label="Steady State Churn" 
                value={activeScenario.retention.monthly.steadyStateChurn} 
                onChange={(v) => updateNestedScenario('retention', { monthly: { ...activeScenario.retention.monthly, steadyStateChurn: v }})} 
                step={1} isPercent
              />
               <NumberInput 
                label="Decay Factor" 
                value={activeScenario.retention.monthly.decayFactor} 
                onChange={(v) => updateNestedScenario('retention', { monthly: { ...activeScenario.retention.monthly, decayFactor: v }})} 
                step={0.1}
                tooltip="Higher = faster drop to steady state"
              />
            </div>
          )}
           {activeScenario.funnel.planMix.annual > 0 && (
            <div className="p-3 bg-slate-50 rounded border border-slate-100">
              <h4 className="text-sm font-bold capitalize mb-2">Annual Retention</h4>
              <NumberInput 
                label="Year 1 Churn" 
                value={activeScenario.retention.annual.year1Churn} 
                onChange={(v) => updateNestedScenario('retention', { annual: { ...activeScenario.retention.annual, year1Churn: v }})} 
                step={1} isPercent
              />
            </div>
          )}
        </div>
      )}

      {/* 5. Costs */}
      <SectionHeader title="5. Operational Costs" isOpen={sections.costs} toggle={() => toggle('costs')} />
      {sections.costs && (
        <div className="p-4 space-y-2 animate-fadeIn">
          <NumberInput 
            label="Fixed Opex (Monthly)" 
            value={activeScenario.costs.fixedOpexMonthly} 
            onChange={(v) => updateNestedScenario('costs', { fixedOpexMonthly: v })} 
            suffix="$" step={100}
          />
          <NumberInput 
            label="Var Cost / Active Sub" 
            value={activeScenario.costs.variableCostPerActiveSub} 
            onChange={(v) => updateNestedScenario('costs', { variableCostPerActiveSub: v })} 
            suffix="$" step={0.01}
          />
        </div>
      )}

      <div className="p-4 mt-8 pb-8 text-xs text-slate-400 text-center">
        v1.0.0 &copy; 2024
      </div>
    </div>
  );
};

