                <Line type="monotone" dataKey="Cash" stroke="#3b82f6" strokeWidth={3} dot={false} name="Cumulative Profit" />
                <ReferenceLine y={0} stroke="#000" />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Data Table */}
      <div id="table-view" className="bg-white rounded-lg border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-4 border-b border-slate-200 bg-slate-50">
           <h3 className="text-lg font-bold text-slate-800">Monthly Detailed Breakdown</h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-xs text-left">
            <thead className="text-xs text-slate-500 uppercase bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-4 py-3 font-semibold">Mo</th>
                <th className="px-4 py-3 font-semibold text-right">Installs</th>
                <th className="px-4 py-3 font-semibold text-right">Payers</th>
                <th className="px-4 py-3 font-semibold text-right">Act. Subs</th>
                <th className="px-4 py-3 font-semibold text-right">Gross Rev</th>
                <th className="px-4 py-3 font-semibold text-right">Net Rev</th>
                <th className="px-4 py-3 font-semibold text-right">Ad Spend</th>
                <th className="px-4 py-3 font-semibold text-right">OpEx</th>
                <th className="px-4 py-3 font-semibold text-right">Profit</th>
                <th className="px-4 py-3 font-semibold text-right">MRR</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {monthlyData.map((row) => (
                <tr key={row.monthIndex} className="hover:bg-slate-50">
                  <td className="px-4 py-2 font-medium text-slate-900">{row.monthIndex}</td>
                  <td className="px-4 py-2 text-right text-slate-600">{formatNumber(row.totalInstalls)}</td>
                  <td className="px-4 py-2 text-right text-slate-600">{formatNumber(row.newPayers)}</td>
                  <td className="px-4 py-2 text-right text-slate-600">{formatNumber(row.activeSubsTotal)}</td>
                  <td className="px-4 py-2 text-right text-slate-600">{formatCurrency(row.grossRevenue)}</td>
                  <td className="px-4 py-2 text-right text-slate-600">{formatCurrency(row.netRevenue)}</td>
                  <td className="px-4 py-2 text-right text-slate-600">{formatCurrency(row.adSpend)}</td>
                  <td className="px-4 py-2 text-right text-slate-600">{formatCurrency(row.fixedOpex + row.variableCosts)}</td>
                  <td className={`px-4 py-2 text-right font-bold ${row.profit >= 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
                    {formatCurrency(row.profit)}
                  </td>
                  <td className="px-4 py-2 text-right text-blue-600 font-medium">{formatCurrency(row.mrr)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

    </div>
  );
};

