import React from 'react';
import { GrowthInput as GrowthInputType } from '../types';

interface NumberInputProps {
  label: string;
  value: number;
  onChange: (val: number) => void;
  step?: number;
  min?: number;
  max?: number;
  suffix?: string;
  tooltip?: string;
  isPercent?: boolean;
}

export const NumberInput: React.FC<NumberInputProps> = ({ 
  label, value, onChange, step = 1, min = 0, max, suffix, tooltip, isPercent 
}) => {
  const displayValue = isPercent ? Math.round(value * 100) : value;

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let val = parseFloat(e.target.value);
    if (isNaN(val)) val = 0;
    if (isPercent) val = val / 100;
    onChange(val);
  };

  return (
    <div className="mb-4">
      <div className="flex justify-between items-center mb-1.5">
        <label className="text-[13px] font-medium text-gray-500 flex items-center gap-1.5">
          {label}
          {tooltip && (
            <div className="group relative flex justify-center">
               <span className="text-gray-300 cursor-help text-[10px] border border-gray-300 rounded-full w-3.5 h-3.5 flex items-center justify-center hover:border-blue-400 hover:text-blue-400 transition-colors">?</span>
               <span className="absolute bottom-full mb-1 hidden group-hover:block w-48 p-2 bg-gray-800 text-white text-xs rounded shadow-lg z-50 text-center">
                 {tooltip}
               </span>
            </div>
          )}
        </label>
        {isPercent && <span className="text-[11px] font-medium text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded">{(value * 100).toFixed(1)}%</span>}
      </div>
      <div className="relative group">
        <input
          type="number"
          className="w-full bg-white border border-gray-200 rounded-lg px-3 py-2 text-[14px] text-gray-900 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all duration-200 placeholder-gray-300 hover:border-gray-300"
          value={displayValue}
          onChange={handleChange}
          step={step}
          min={min}
          max={max}
        />
        {suffix && (
          <span className="absolute right-3 top-2 text-[13px] text-gray-400 pointer-events-none font-medium">
            {suffix}
          </span>
        )}
      </div>
    </div>
  );
};

export const GrowthInput: React.FC<{ 
  label: string; 
  value: GrowthInputType; 
  onChange: (val: GrowthInputType) => void; 
  suffix?: string 
}> = ({ label, value, onChange, suffix }) => {
  return (
    <div className="mb-5 p-3.5 bg-white rounded-xl border border-gray-200 shadow-sm">
      <label className="text-[13px] font-semibold text-gray-700 block mb-3">{label}</label>
      <div className="flex gap-3">
        <div className="flex-1">
          <label className="text-[10px] font-medium text-gray-400 uppercase tracking-wide mb-1 block">Start Value</label>
          <div className="relative">
            <input 
              type="number" 
              value={value.startValue}
              onChange={(e) => onChange({...value, startValue: parseFloat(e.target.value) || 0})}
              className="w-full border border-gray-200 rounded-lg px-2.5 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all"
            />
            {suffix && <span className="absolute right-2.5 top-1.5 text-xs text-gray-400">{suffix}</span>}
          </div>
        </div>
        <div className="w-24">
          <label className="text-[10px] font-medium text-gray-400 uppercase tracking-wide mb-1 block">MoM Growth</label>
          <div className="relative">
            <input 
              type="number" 
              value={Math.round(value.growthRateMonthly * 100)}
              onChange={(e) => onChange({...value, growthRateMonthly: (parseFloat(e.target.value) || 0)/100})}
              className="w-full border border-gray-200 rounded-lg px-2.5 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all text-right pr-6"
            />
             <span className="absolute right-2.5 top-1.5 text-xs text-gray-400">%</span>
          </div>
        </div>
      </div>
    </div>
  );
};

