             <button onClick={() => addScenario(BEAR_CASE_PRESET)} className="text-[10px] px-2.5 py-1 bg-rose-50 text-rose-600 rounded-md font-medium hover:bg-rose-100 transition-colors">Bear</button>
           </div>
        </div>
        <div className="flex gap-2">
            <div className="relative flex-1">
              <select 
                className="w-full appearance-none bg-white border border-gray-200 text-gray-700 text-[13px] font-medium rounded-lg pl-3 pr-8 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 shadow-sm"
                value={activeScenarioId}
                onChange={(e) => switchScenario(e.target.value)}
