export const ArrayInput: React.FC<{
  label: string;
  value: number[];
  onChange: (val: number[]) => void;
  tooltip?: string;
  rows?: number;
}> = ({ label, value, onChange, tooltip, rows = 3 }) => {
  const [localStr, setLocalStr] = useState(value.join(', '));
  const isTypingRef = useRef(false);

  // Sync with external updates unless typing
  useEffect(() => {
    if (!isTypingRef.current) {
      setLocalStr(value.join(', '));
    }
    isTypingRef.current = false;
  }, [value.join(',')]);

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    isTypingRef.current = true;
    setLocalStr(e.target.value);
  };

  const handleBlur = () => {
    isTypingRef.current = false;
    const parts = localStr.split(',');
    const nums = parts.map(p => {
        const clean = p.trim();
        if (clean === '') return null;
        const n = parseFloat(clean);
        return isNaN(n) ? null : n;
    }).filter((n): n is number => n !== null);

    onChange(nums);
    setLocalStr(nums.join(', '));
  };

  return (
    <div className="mb-5">
       <InputLabel label={label} tooltip={tooltip} />
       <textarea 
          className="w-full bg-white border border-gray-200 rounded-lg px-3 py-2.5 text-[12px] text-gray-800 shadow-[0_1px_2px_rgba(0,0,0,0.02)] focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 transition-all duration-200 placeholder-gray-300 hover:border-gray-300 font-mono leading-relaxed"
          rows={rows}
          value={localStr}
          onChange={handleChange}
          onBlur={handleBlur}
       />
       <p className="text-[10px] text-gray-400 mt-1.5 px-0.5">Comma-separated survival rates (0.0 to 1.0)</p>
    </div>
  );
};

