    updateScenario, updateNestedScenario 
  } = useStore();

  const activeScenario = scenarios.find(s => s.id === activeScenarioId)!;

  const [sections, setSections] = useState({
    marketing: true,
    funnel: false,
    plans: false,
    retention: false,
    costs: false
  });

  const toggle = (key: keyof typeof sections) => 
    setSections(prev => ({ ...prev, [key]: !prev[key] }));

  // Helper for Advanced CPI Update
  const handleAdvancedCpiUpdate = (newBreakdown: ChannelMetric[]) => {
      // Logic: Weighted Average based on Hypothetical Budget ($1,000)
      // Projected Installs = (Budget * Share%) / Channel CPI
      // Blended CPI = Budget / Sum(Projected Installs)

      const budget = 1000;
      let totalInstalls = 0;

      newBreakdown.forEach(ch => {
          if (ch.share > 0 && ch.cpi > 0) {
              const spend = budget * ch.share;
              const installs = spend / ch.cpi;
              totalInstalls += installs;
          }
      });

      const blendedCpi = totalInstalls > 0 ? budget / totalInstalls : 0;

      updateNestedScenario('marketing', {
          cpi: { ...activeScenario.marketing.cpi, startValue: blendedCpi },
          cpiBreakdown: newBreakdown
      });
  };

  const totalShare = activeScenario.marketing.cpiBreakdown?.reduce((sum, ch) => sum + ch.share, 0) || 0;
  const isShareValid = Math.abs(totalShare - 1.0) < 0.01;

