                            updateScenario({ plans: newPlans });
                          }} 
                          suffix="$"
                        />
                        <NumberInput 
                          label="Year 1 Comm." 
                          value={activeScenario.plans[p].storeCommissionYear1} 
                          onChange={(v) => {
                            const newPlans = { ...activeScenario.plans };
                            newPlans[p] = { ...newPlans[p], storeCommissionYear1: v };
                            updateScenario({ plans: newPlans });
