// ---------------------------
// Web SaaS Calculator - Data Model (TypeScript)
// ---------------------------

export type ScenarioId = "bear" | "base" | "bull";
export type HorizonMonths = 3 | 6 | 12 | 18 | 24 | 36 | 48 | 60;

export type CurrencyCode = "USD" | "CAD" | "AUD" | "NZD" | "EUR" | "GBP";
export type BillingPeriod = "monthly" | "annual";
export type ChannelKey =
  | "google_search"
  | "google_display"
  | "meta"
  | "tiktok"
  | "youtube"
  | "reddit"
  | "x"
  | "linkedin"
  | "affiliate"
  | "influencer"
  | "seo"
  | "email"
  | "referral"
  | "other";

export type Percentage = number; // 0..1 internally
export type Money = number; // in scenario currency

/** Helper for "Start + MoM" style inputs you already use */
export interface StartMoM {
  start: number;      // value at month 1
  momPct: number;     // month-over-month change (e.g., 0.05 = +5%)
}

/** Month-indexed time series (length = horizonMonths) */
export type MonthlySeries<T = number> = T[];

/** Common "either constant or per-month series" pattern */
export type ValueByMonth =
  | { kind: "constant"; value: number }
  | { kind: "series"; values: MonthlySeries<number> }
  | { kind: "start_mom"; startMoM: StartMoM };

// ---------------------------
// Root: Web SaaS Project Model
// ---------------------------

export interface WebSaasModel {
  version: "web-saas-v1";
  currency: CurrencyCode;
  horizonMonths: HorizonMonths;
  scenarios: Record<ScenarioId, WebSaasScenario>;
  // Which scenario is currently selected in UI
  activeScenario: ScenarioId;
  // Optional: global notes for the file
  notes?: string;
}

// ---------------------------
// Scenario Model
// ---------------------------

export interface WebSaasScenario {
  id: ScenarioId;
  name: string; // "Base Case", "Bull Case", "Bear Case"

  acquisition: WebAcquisitionModel;
  funnel: WebFunnelModel;

  pricing: WebPricingModel;
  retention: WebRetentionModel;

  costs: WebCostModel;
  assumptions: WebAssumptionsModel;

  // Optional: constraints for health checks
  targets?: WebTargets;
}

// ---------------------------
// Acquisition (Spend + Channel Mix)
// ---------------------------

/**
 * Acquisition is modeled at monthly resolution.
 * You can support:
 *  - spend per channel, then either (a) CAC direct input or (b) CPC/CPM + funnel.
 *  - organic sources (SEO/referral/email) can be modeled as "free" channels.
 */
export interface WebAcquisitionModel {
  // Total spend plan (if you want a single spend plan + channel weights)
  totalPaidSpend: ValueByMonth;

  // Channel allocation weights (sum to 1.0 for paid channels only)
  channelWeights: Partial<Record<ChannelKey, Percentage>>;

  // Per-channel cost model
  channels: Partial<Record<ChannelKey, WebChannelModel>>;

  // Organic baseline sessions (optional) - useful for SEO/email/referral growth
  organicSessions?: ValueByMonth;

  // Optional: if you want to model "incremental organic lift" from paid
  organicMultiplier?: number; // e.g., 0.3 meaning +30% organic sessions per paid session
}

export type ChannelCostMode =
  | "cac_direct"     // user enters CAC per paid customer (fast)
  | "cpc"            // user enters CPC
  | "cpm"            // user enters CPM + CTR
  | "hybrid";        // allow both; prefer CPC if present

export interface WebChannelModel {
  enabled: boolean;

  // If channel is paid, it consumes spend; if organic, cost can be 0
  isPaid: boolean;

  costMode: ChannelCostMode;

  // Spend override (optional). If present, use this instead of totalPaidSpend * weights
  monthlySpend?: ValueByMonth;

  // Cost inputs
  cpc?: ValueByMonth;         // $ per click
  cpm?: ValueByMonth;         // $ per 1000 impressions
  ctr?: ValueByMonth;         // click-through rate (0..1) if using CPM
  cacDirect?: ValueByMonth;   // $ per paid customer (bypasses funnel)

  // Optional: quality multipliers by channel (affects trial->paid or churn)
  quality?: {
    trialToPaidMultiplier?: number; // e.g., 1.1
    churnMultiplier?: number;       // e.g., 0.9 lowers churn
  };
}

// ---------------------------
// Funnel (Web)
// ---------------------------

export type WebFunnelMode =
  | "full_funnel"     // sessions -> signup -> activation -> trial -> paid
  | "trial_only"      // sessions -> trial -> paid (no signup/activation separation)
  | "paid_direct";    // spend -> paid (CAC direct), funnel optional for reporting

export interface WebFunnelModel {
  mode: WebFunnelMode;

  // If you have both free signup and trial, model all.
  // Internally use 0..1 decimals.
  sessionToSignup?: Percentage;       // visit -> signup
  signupToActivation?: Percentage;    // signup -> activated (aha moment)
  activationToTrial?: Percentage;     // activated -> starts trial (if trial exists)
  trialToPaid?: Percentage;           // trial -> paid

  // If you skip trial:
  activationToPaid?: Percentage;      // activated -> paid (no trial)

  // If you use "trial_only" without signup:
  sessionToTrial?: Percentage;        // visit -> trial
  // still uses trialToPaid

  // Purchase friction / payment failures (web-specific)
  checkoutToPaid?: Percentage;        // optional: checkout started -> paid

  // Refund / cancellation behavior for web purchases
  refundRate?: Percentage;            // blended refunds (0..1)

  // If you want to model organic vs paid conversion differences later:
  perChannelOverrides?: Partial<Record<ChannelKey, Partial<WebFunnelOverrides>>>;
}

export interface WebFunnelOverrides {
  sessionToSignup?: Percentage;
  signupToActivation?: Percentage;
  activationToTrial?: Percentage;
  trialToPaid?: Percentage;
  activationToPaid?: Percentage;
  sessionToTrial?: Percentage;
  refundRate?: Percentage;
}

// ---------------------------
// Pricing / Plans (Web SaaS)
// ---------------------------

export interface WebPricingModel {
  plans: WebPlan[];
  planMix: Record<string, Percentage>; // key = planId, sums to 1.0 among new paid

  // Optional: discounts / promos
  promo?: {
    enabled: boolean;
    // % off applied to first invoice only (simple)
    firstInvoiceDiscountPct?: Percentage;
    // coupon redemption rate among new paid users
    redemptionRate?: Percentage;
  };
}

export interface WebPlan {
  planId: string;
  name: string;

  billingPeriod: BillingPeriod; // monthly or annual
  listPrice: Money;             // sticker price

  // Optional: multiple seats or usage tiers
  seatsIncluded?: number;
  maxUsageIncluded?: number;

  // Optional: annual discount relative to monthly
  effectiveMonthlyPrice?: Money; // if annual, listPrice/12; store for display
}

// ---------------------------
// Retention / Churn (Web SaaS)
// ---------------------------

export type RetentionModelType =
  | "simple"        // month1 churn + steady churn + decay
  | "curve_table"   // explicit churn/retention by month age
  | "nr_based";     // optional v2: NRR model (expansion/contraction)

export interface WebRetentionModel {
  modelType: RetentionModelType;

  // For "simple" model
  monthly?: {
    month1Churn: Percentage;  // churn after first paid month
    steadyChurn: Percentage;  // long-run churn (months 3+)
    decaySpeed: number;       // 0..1, higher = faster convergence to steady
  };

  // Annual renewal for annual plans (churn at renewal time)
  annual?: {
    year1Churn: Percentage;   // churn at first annual renewal
    year2PlusChurn: Percentage;
  };

  // For "curve_table" model: churn by customer age (months since first paid)
  churnCurveByMonthAge?: MonthlySeries<Percentage>; // length >= horizonMonths

  // Web-specific: involuntary churn / dunning
  payments?: {
    failedPaymentRate: Percentage;     // invoices that fail initially
    recoveryRate: Percentage;          // % recovered via dunning
  };

  // Optional: reactivation (winback)
  reactivationRateMonthly?: Percentage;
}

// ---------------------------
// Costs (Web SaaS)
// ---------------------------

export interface WebCostModel {
  // Fixed monthly operating costs (team, tools, rent, etc.)
  fixedOpex: ValueByMonth;

  // Variable costs (COGS)
  variable: {
    // infra/support per active paid subscriber per month
    costPerActiveSubscriber?: Money;

    // infra/support per active user (if you have non-paying actives)
    costPerActiveUser?: Money;

    // support tickets model (optional)
    support?: {
      costPerTicket: Money;
      ticketsPer1000ActiveSubscribers: number;
    };

    // usage-based (optional): cost per usage unit
    usage?: {
      enabled: boolean;
      costPerUnit: Money;
      avgUnitsPerActiveSubscriberPerMonth: number;
    };
  };

  // Payment processing fees (Stripe etc.)
  payments: {
    processorPct: Percentage; // e.g., 0.029
    processorFixedFee: Money; // e.g., 0.30
  };

  // Taxes (optional)
  taxes?: {
    enabled: boolean;
    vatPct?: Percentage;
    salesTaxPct?: Percentage;
  };
}

// ---------------------------
// Global Assumptions
// ---------------------------

export interface WebAssumptionsModel {
  // Revenue recognition
  revenueRecognition: "cash" | "accrual"; // cash = annual upfront; accrual = spread monthly

  // Discount rate for LTV (optional)
  discountRateAnnual?: Percentage; // e.g., 0.10

  // Attribution window (reporting), optional
  attributionWindowDays?: number;

  // Define whether CAC is computed on "gross payers" or "net payers after refunds"
  cacBasis: "gross_payers" | "net_payers";
}

// ---------------------------
// Targets / Health Checks
// ---------------------------

export interface WebTargets {
  ltvToCacTarget?: number;       // e.g., 3.0
  paybackMonthsTarget?: number;  // e.g., 6 or 12
  grossMarginTarget?: Percentage;
}

// ---------------------------
// Result types (optional, but helpful)
// ---------------------------

export interface WebSaasMonthlyOutputRow {
  monthIndex: number; // 1..H
  paidSpend: Money;

  // Traffic
  paidSessions: number;
  organicSessions: number;
  totalSessions: number;

  // Funnel counts
  signups: number;
  activated: number;
  trials: number;
  newPaid: number;        // gross new paid
  newPaidNet: number;     // after refunds / failed payment non-recovery

  // Subscribers
  activePaidSubscribers: number;

  // Revenue
  grossRevenue: Money;
  refunds: Money;
  netRevenueBeforeProcessor: Money;
  processorFees: Money;
  netRevenue: Money;

  // Costs
  variableCosts: Money;
  fixedOpex: Money;

  // Profit
  contribution: Money;
  profit: Money;
  cumulativeProfit: Money;
}

