          status={summary.breakEvenMonth ? 'good' : 'bad'}
        />
      </div>

      {/* Charts Row 1 */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-10">
        {/* Cohort Payback */}
